    print('  of the stored edges leaving a def that ran, share recorded:', '  '.join(
        f"{g} {c['edges from defs that ran, recorded', g] / c['edges from defs that ran', g]:.2f} "
        f"of {c['edges from defs that ran', g]:,}" for g in ('released', 'rebuilt')))
    for k, d in (('recorded either way', 'edges from defs that ran'),
                 ('no def-member pairs, recorded either way', 'edges from defs that ran, no def-member pairs')):
        print(f'  same, {k}:', '  '.join(
            f"{g} {c[f'edges from defs that ran, {k}', g] / c[d, g]:.2f}" for g in ('released', 'rebuilt')))
    print(f"  callee is a protocol method in {c['callee is a protocol method']} of {c['all except dispatch', 'n']}"
